    entries.push({
      hour: match[2],
      level: match[3],
      component: match[4],
      message: match[5]
    });
  }
}

const levelCounts: Map<string, number> = new Map();
for (const e of entries) {
  levelCounts.set(e.level, (levelCounts.get(e.level) || 0) + 1);
}

const errorComponentCounts: Map<string, number> = new Map();
const errorMessages: Set<string> = new Set();
for (const e of entries) {
  if (e.level === 'ERROR') {
    errorComponentCounts.set(e.component, (errorComponentCounts.get(e.component) || 0) + 1);
    errorMessages.add(e.message);
  }
}

const hourCounts: Map<string, number> = new Map();
