output.push('=== Log Analysis ===');
output.push('');
output.push('Entries by Level:');

const sortedLevels = [...levelCounts.entries()].sort((a, b) => a[0].localeCompare(b[0]));
for (const [level, count] of sortedLevels) {
  output.push(`  ${level}: ${count}`);
}

output.push('');

let maxErrorComponent = '';
let maxErrorCount = 0;
for (const [comp, count] of errorComponentCounts) {
  if (count > maxErrorCount || (count === maxErrorCount && comp < maxErrorComponent)) {
    maxErrorCount = count;
    maxErrorComponent = comp;
  }
}
output.push(`Component with Most Errors: ${maxErrorComponent} (${maxErrorCount} errors)`);
output.push('');

output.push('Unique Error Messages:');
const sortedErrors = [...errorMessages].sort();
for (const msg of sortedErrors) {
  output.push(`  - ${msg}`);
}

output.push('');

let busiestHour = '';
let busiestCount = 0;
for (const [hour, count] of hourCounts) {
  if (count > busiestCount || (count === busiestCount && hour < busiestHour)) {
    busiestCount = count;
    busiestHour = hour;
  }
}
output.push(`Busiest Hour: ${busiestHour}:00 (${busiestCount} entries)`);

process.stdout.write(output.join('\n') + '\n');

