import java.io.*;
import java.util.*;
import java.util.regex.*;

public class Main {
    public static void main(String[] args) throws Exception {
        String filePath = "<tmp>";

        List<String> lines = new ArrayList<>();
        try (BufferedReader br = new BufferedReader(new FileReader(filePath))) {
            String line;
            while ((line = br.readLine()) != null) {
                if (!line.trim().isEmpty()) {
                    lines.add(line.trim());
                }
            }
        }

        Pattern pattern = Pattern.compile("^\\[(\\d{4}-\\d{2}-\\d{2} (\\d{2}):\\d{2}:\\d{2})\\] (\\S+) \\(([^)]+)\\) - (.+)$");

        Map<String, Integer> levelCounts = new TreeMap<>();
        Map<String, Integer> componentErrors = new TreeMap<>();
        Set<String> errorMessages = new TreeSet<>();
        Map<String, Integer> hourCounts = new TreeMap<>();

        for (String line : lines) {
            Matcher m = pattern.matcher(line);
            if (m.matches()) {
                String timestamp = m.group(1);
                String hour = m.group(2);
                String level = m.group(3);
                String component = m.group(4);
                String message = m.group(5);

                levelCounts.put(level, levelCounts.getOrDefault(level, 0) + 1);

                if (level.equals("ERROR")) {
                    componentErrors.put(component, componentErrors.getOrDefault(component, 0) + 1);
                    errorMessages.add(message);
                }

                hourCounts.put(hour, hourCounts.getOrDefault(hour, 0) + 1);
            }
        }

        String topComponent = "";
        int topCount = 0;
        for (Map.Entry<String, Integer> entry : componentErrors.entrySet()) {
            if (entry.getValue() > topCount || (entry.getValue() == topCount && entry.getKey().compareTo(topComponent) < 0)) {
                topCount = entry.getValue();
                topComponent = entry.getKey();
            }
        }

        String busiestHour = "00";
        int busiestCount = 0;
        for (Map.Entry<String, Integer> entry : hourCounts.entrySet()) {
            if (entry.getValue() > busiestCount || (entry.getValue() == busiestCount && entry.getKey().compareTo(busiestHour) < 0)) {
                busiestCount = entry.getValue();
                busiestHour = entry.getKey();
            }
        }

        StringBuilder sb = new StringBuilder();
        sb.append("=== Log Analysis ===\n");
        sb.append("\n");
        sb.append("Entries by Level:\n");
        for (Map.Entry<String, Integer> entry : levelCounts.entrySet()) {
            sb.append("  ").append(entry.getKey()).append(": ").append(entry.getValue()).append("\n");
        }
        sb.append("\n");
        sb.append("Component with Most Errors: ").append(topComponent).append(" (").append(topCount).append(" errors)\n");
        sb.append("\n");
        sb.append("Unique Error Messages:\n");
        for (String msg : errorMessages) {
            sb.append("  - ").append(msg).append("\n");
        }
        sb.append("\n");
        sb.append("Busiest Hour: ").append(busiestHour).append(":00 (").append(busiestCount).append(" entries)\n");

        System.out.print(sb.toString());
    }
}

