import * as fs from 'fs';

function formatNumberWithCommas(n: number, decimals: number = 0): string {
    const fixed = n.toFixed(decimals);
    const parts = fixed.split('.');
    let intPart = parts[0];
    const decPart = parts.length > 1 ? '.' + parts[1] : '';
    const negative = intPart.startsWith('-');
    if (negative) intPart = intPart.substring(1);
    const withCommas = intPart.replace(/\B(?=(\d{3})+(?!\d))/g, ',');
    return (negative ? '-' : '') + withCommas + decPart;
}

const csvPath = '<tmp>';
const content = fs.readFileSync(csvPath, 'utf-8');
const lines = content.trim().split('\n');

const header = lines[0].split(',').map(h => h.trim());
const idx = {
    employee_id: header.indexOf('employee_id'),
    name: header.indexOf('name'),
    department: header.indexOf('department'),
    salary: header.indexOf('salary'),
    start_date: header.indexOf('start_date'),
    rating: header.indexOf('rating'),
};

interface Employee {
    employee_id: string;
    name: string;
    department: string;
    salary: number;
    start_date: string;
    rating: string;
}

const employees: Employee[] = [];
for (let i = 1; i < lines.length; i++) {
    const cols = lines[i].split(',').map(c => c.trim());
    if (cols.length < 6) continue;
    employees.push({
        employee_id: cols[idx.employee_id],
        name: cols[idx.name],
        department: cols[idx.department],
        salary: parseFloat(cols[idx.salary]),
        start_date: cols[idx.start_date],
        rating: cols[idx.rating],
    });
}

const deptSalaries: Map<string, number[]> = new Map();
for (const emp of employees) {
    if (!deptSalaries.has(emp.department)) {
        deptSalaries.set(emp.department, []);
    }
    deptSalaries.get(emp.department)!.push(emp.salary);
}

const sortedDepts = Array.from(deptSalaries.keys()).sort();

let highestPaid = employees[0];
for (const emp of employees) {
    if (emp.salary > highestPaid.salary) {
        highestPaid = emp;
    }
}

const deptCounts: Map<string, number> = new Map();
for (const emp of employees) {
    deptCounts.set(emp.department, (deptCounts.get(emp.department) || 0) + 1);
}

const deptsWithMoreThan2 = sortedDepts.filter(d => (deptCounts.get(d) || 0) > 2);

const totalBudget = employees.reduce((sum, e) => sum + e.salary, 0);

