#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

struct Employee {
    char *name;
    char *department;
    double salary;
};

struct DeptInfo {
    char *name;
    double total;
    int count;
};

static void format_comma(char *buf, double value, int decimals) {
    char tmp[128];
    if (decimals == 0) {
        snprintf(tmp, sizeof(tmp), "%.0f", value);
    } else {
        snprintf(tmp, sizeof(tmp), "%.*f", decimals, value);
    }
    int len = (int)strlen(tmp);
    int dot_pos = -1;
    for (int i = 0; i < len; i++) {
        if (tmp[i] == '.') { dot_pos = i; break; }
    }
    int int_len = (dot_pos == -1) ? len : dot_pos;
    int idx = 0;
    for (int i = 0; i < int_len; i++) {
        if (i > 0 && (int_len - i) % 3 == 0) {
            buf[idx++] = ',';
        }
        buf[idx++] = tmp[i];
    }
    for (int i = int_len; i < len; i++) {
        buf[idx++] = tmp[i];
    }
    buf[idx] = '\0';
}

static int cmp_depts(const void *a, const void *b) {
    const struct DeptInfo *da = (const struct DeptInfo *)a;
    const struct DeptInfo *db = (const struct DeptInfo *)b;
    return strcmp(da->name, db->name);
}

static char *dup_str(const char *s) {
    size_t n = strlen(s) + 1;
    char *p = (char *)malloc(n);
    if (p) memcpy(p, s, n);
    return p;
}

int main(void) {
    const char *path = "<tmp>";
    FILE *fp = fopen(path, "r");
    if (!fp) {
        fprintf(stderr, "Cannot open file\n");
        return 1;
    }

    size_t emp_cap = 256;
    size_t emp_count = 0;
    struct Employee *emps = (struct Employee *)malloc(emp_cap * sizeof(struct Employee));
    if (!emps) { fclose(fp); return 1; }

    char *line = NULL;
    size_t line_cap = 0;
    ssize_t line_len;
    int first_line = 1;

    while ((line_len = getline(&line, &line_cap, fp)) != -1) {
        /* strip trailing newline/carriage return */
        while (line_len > 0 && (line[line_len - 1] == '\n' || line[line_len - 1] == '\r')) {
            line[--line_len] = '\0';
        }
        if (line_len == 0) continue;

        if (first_line) {
            first_line = 0;
            /* check if it's a header */
            if (strncmp(line, "employee_id", 11) == 0) {
                continue;
            }
        }

        /* parse CSV: employee_id, name, department, salary, start_date, rating */
        char *fields[6] = {0};
        int nf = 0;
        char *p = line;
        fields[nf++] = p;
        while (*p && nf < 6) {
            if (*p == ',') {
                *p = '\0';
                p++;
                fields[nf++] = p;
            } else {
                p++;
            }
        }
        if (nf < 6) continue;

        if (emp_count >= emp_cap) {
            emp_cap *= 2;
            emps = (struct Employee *)realloc(emps, emp_cap * sizeof(struct Employee));
            if (!emps) { free(line); fclose(fp); return 1; }
        }

        emps[emp_count].name = dup_str(fields[1]);
        emps[emp_count].department = dup_str(fields[2]);
        emps[emp_count].salary = atof(fields[3]);
        emp_count++;
    }

    free(line);
    fclose(fp);

    /* Build department info */
    size_t dept_cap = 64;
    size_t dept_count = 0;
    struct DeptInfo *depts = (struct DeptInfo *)malloc(dept_cap * sizeof(struct DeptInfo));
    if (!depts) return 1;

    for (size_t i = 0; i < emp_count; i++) {
        int found = 0;
        for (size_t d = 0; d < dept_count; d++) {
            if (strcmp(depts[d].name, emps[i].department) == 0) {
                depts[d].total += emps[i].salary;
                depts[d].count++;
                found = 1;
                break;
            }
        }
        if (!found) {
            if (dept_count >= dept_cap) {
                dept_cap *= 2;
                depts = (struct DeptInfo *)realloc(depts, dept_cap * sizeof(struct DeptInfo));
                if (!depts) return 1;
            }
            depts[dept_count].name = dup_str(emps[i].department);
            depts[dept_count].total = emps[i].salary;
            depts[dept_count].count = 1;
            dept_count++;
        }
    }

    /* Sort departments alphabetically */
    qsort(depts, dept_count, sizeof(struct DeptInfo), cmp_depts);

    /* Find highest paid */
    double max_salary = -1.0;
    const char *max_name = "";
    for (size_t i = 0; i < emp_count; i++) {
        if (emps[i].salary > max_salary) {
            max_salary = emps[i].salary;
            max_name = emps[i].name;
        }
    }

    /* Total budget */
    double total_budget = 0.0;
    for (size_t i = 0; i < emp_count; i++) {
        total_budget += emps[i].salary;
    }

    /* Output */
    printf("=== Salary Report ===\n");
    printf("\n");
    printf("Average Salary by Department:\n");
    for (size_t d = 0; d < dept_count; d++) {
        double avg = depts[d].total / (double)depts[d].count;
        char numbuf[128];
        format_comma(numbuf, avg, 2);
        printf("  %s: $%s\n", depts[d].name, numbuf);
    }
    printf("\n");
    {
        char numbuf[128];
        format_comma(numbuf, max_salary, 0);
        printf("Highest Paid: %s ($%s)\n", max_name, numbuf);
    }
    printf("\n");
    printf("Departments with >2 employees:\n");
    for (size_t d = 0; d < dept_count; d++) {
        if (depts[d].count > 2) {
            printf("  %s (%d employees)\n", depts[d].name, depts[d].count);
        }
    }
    printf("\n");
    {
        char numbuf[128];
        format_comma(numbuf, total_budget, 0);
        printf("Total Budget: $%s\n", numbuf);
    }

    /* Cleanup */
    for (size_t i = 0; i < emp_count; i++) {
        free(emps[i].name);
        free(emps[i].department);
    }
    free(emps);
    for (size_t d = 0; d < dept_count; d++) {
        free(depts[d].name);
    }
    free(depts);

    return 0;
}
