use std::collections::HashMap;
use std::fs;

fn format_with_commas(n: f64, decimals: usize) -> String {
    let negative = n < 0.0;
    let n = n.abs();
    let int_part = n as u64;
    let frac_part = (n - int_part as f64) * 10f64.powi(decimals as i32);
    let frac_int = frac_part as u64;

    let int_str = int_part.to_string();
    let chars: Vec<char> = int_str.chars().collect();
    let mut comma_str = String::new();
    for (i, c) in chars.iter().enumerate() {
        if i > 0 && (chars.len() - i) % 3 == 0 {
            comma_str.push(',');
        }
        comma_str.push(*c);
    }

    let sign = if negative { "-" } else { "" };
    if decimals > 0 {
        let frac_str = format!("{:0width$}", frac_int, width = decimals);
        format!("{}${}.{}", sign, comma_str, frac_str)
    } else {
        format!("{}${}", sign, comma_str)
    }
}

fn main() {
    let path = "<tmp>";
    let content = fs::read_to_string(path).expect("Failed to read file");

    let lines: Vec<&str> = content.lines().collect();
    let header = lines[0];
    let cols: Vec<&str> = header.split(',').map(|s| s.trim()).collect();
