    let dept_idx = cols.iter().position(|c| c == "department").unwrap();
    let salary_idx = cols.iter().position(|c| c == "salary").unwrap();

    let mut names: Vec<String> = Vec::new();
    let mut departments: Vec<String> = Vec::new();
    let mut salaries: Vec<f64> = Vec::new();

    for line in &lines[1..] {
        if line.trim().is_empty() {
            continue;
        }
        let fields: Vec<&str> = line.split(',').map(|s| s.trim()).collect();
        let name = fields[name_idx].to_string();
        let dept = fields[dept_idx].to_string();
        let salary: f64 = fields[salary_idx].parse().unwrap();
        names.push(name);
        departments.push(dept);
        salaries.push(salary);
    }

    let mut dept_sum: HashMap<String, f64> = HashMap::new();
    let mut dept_count: HashMap<String, usize> = HashMap::new();

    for i in 0..departments.len() {
