    println!("Average Salary by Department:");
    for dept in &sorted_depts {
        let avg = dept_sum[dept] / dept_count[dept] as f64;
        println!("  {}: {}", dept, format_with_commas(avg, 2));
    }
    println!();
    println!("Highest Paid: {} ({})", names[max_idx], format_with_commas(salaries[max_idx], 0));
    println!();
    println!("Departments with >2 employees:");
    for dept in &sorted_depts {
        let count = dept_count[dept];
        if count > 2 {
            println!("  {} ({} employees)", dept, count);
        }
    }
    println!();
    println!("Total Budget: {}", format_with_commas(total, 0));
