use std::collections::BTreeMap;
use std::fs;

fn main() {
    let path = "<tmp>";
    let content = fs::read_to_string(path).expect("Failed to read log file");

    let mut level_counts: BTreeMap<String, usize> = BTreeMap::new();
    let mut error_component_counts: BTreeMap<String, usize> = BTreeMap::new();
    let mut error_messages: BTreeMap<String, ()> = BTreeMap::new();
    let mut hour_counts: BTreeMap<u32, usize> = BTreeMap::new();

    for line in content.lines() {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }

        let close_bracket = line.find(']').unwrap_or(0);
        let timestamp = &line[1..close_bracket];
        let hour: u32 = timestamp[11..13].parse().unwrap_or(0);
        *hour_counts.entry(hour).or_insert(0) += 1;

        let rest = &line[close_bracket + 2..];

        let level_end = rest.find(' ').unwrap_or(rest.len());
        let level = &rest[..level_end];
        *level_counts.entry(level.to_string()).or_insert(0) += 1;

        let after_level = &rest[level_end + 1..];
        let comp_start = after_level.find('(').unwrap_or(0);
        let comp_end = after_level.find(')').unwrap_or(comp_start + 1);
        let component = &after_level[comp_start + 1..comp_end];

        let after_comp = &after_level[comp_end + 1..];
        let message = after_comp.trim_start_matches(" - ").to_string();

        if level == "ERROR" {
            *error_component_counts.entry(component.to_string()).or_insert(0) += 1;
            error_messages.insert(message, ());
        }
    }

    println!("=== Log Analysis ===");
    println!();
    println!("Entries by Level:");
    for (level, count) in &level_counts {
        println!("  {}: {}", level, count);
    }
    println!();

    let (top_comp, top_count) = error_component_counts
        .iter()
        .max_by_key(|(_, c)| c)
        .map(|(k, v)| (k.clone(), *v))
        .unwrap_or_else(|| ("none".to_string(), 0));
    println!("Component with Most Errors: {} ({} errors)", top_comp, top_count);
    println!();

    println!("Unique Error Messages:");
    for msg in error_messages.keys() {
        println!("  - {}", msg);
    }
    println!();

    let (busiest_hour, busiest_count) = hour_counts
        .iter()
        .max_by_key(|(_, c)| c)
        .map(|(h, c)| (*h, *c))
        .unwrap_or((0, 0));
    println!("Busiest Hour: {:02}:00 ({} entries)", busiest_hour, busiest_count);
}

