import * as fs from 'fs';

interface Edge {
    from: string;
    to: string;
    weight: number;
}

interface Graph {
    nodes: string[];
    edges: Edge[];
}

function main(): void {
    const data: string = fs.readFileSync(
        '<tmp>',
        'utf-8'
    );
    const graph: Graph = JSON.parse(data);

    const adj: Map<string, Array<{ to: string; weight: number }>> = new Map();
    for (const node of graph.nodes) {
        adj.set(node, []);
    }
    for (const edge of graph.edges) {
        adj.get(edge.from)!.push({ to: edge.to, weight: edge.weight });
        adj.get(edge.to)!.push({ to: edge.from, weight: edge.weight });
    }

    const dist: Map<string, number> = new Map();
    for (const node of graph.nodes) {
        dist.set(node, Infinity);
    }
    dist.set('A', 0);

    const visited: Set<string> = new Set();

    for (let i = 0; i < graph.nodes.length; i++) {
        let u: string | null = null;
        let minDist = Infinity;
        for (const node of graph.nodes) {
            if (!visited.has(node) && dist.get(node)! < minDist) {
                minDist = dist.get(node)!;
                u = node;
            }
        }

        if (u === null) break;

        visited.add(u);

        const neighbors = adj.get(u)!;
        for (const { to, weight } of neighbors) {
            const alt = dist.get(u)! + weight;
            if (alt < dist.get(to)!) {
                dist.set(to, alt);
            }
        }
    }

    console.log('=== Shortest Paths from A ===');
    console.log('');
    const sortedNodes = [...graph.nodes].sort();
    for (const node of sortedNodes) {
        const d = dist.get(node)!;
        console.log(`A -> ${node}: ${d}`);
    }
}

main();

