import java.util.*;
import java.nio.file.*;

public class Main {
    static class JsonParser {
        private String input;
        private int pos;

        public JsonParser(String input) {
            this.input = input;
            this.pos = 0;
        }

        public Object parse() {
            skipWhitespace();
            Object result = parseValue();
            return result;
        }

        private Object parseValue() {
