        int found = 0;
        for (int j = 0; j < num_levels; j++) {
            if (strcmp(levels[j], entries[i].level) == 0) {
                level_counts[j]++;
                found = 1;
                break;
            }
        }
        if (!found) {
            levels[num_levels] = strdup(entries[i].level);
            level_counts[num_levels] = 1;
            num_levels++;
        }
    }

    int *level_idx = malloc((size_t)(num_levels > 0 ? num_levels : 1) * sizeof(int));
    for (int i = 0; i < num_levels; i++) level_idx[i] = i;
    for (int i = 0; i < num_levels; i++)
        for (int j = i + 1; j < num_levels; j++)
            if (strcmp(levels[level_idx[i]], levels[level_idx[j]]) > 0) {
                int t = level_idx[i]; level_idx[i] = level_idx[j]; level_idx[j] = t;
            }

    /* Component with Most Errors */
    char **err_comps = malloc((size_t)(count + 1) * sizeof(char *));
    int *err_counts = malloc((size_t)(count + 1) * sizeof(int));
    int num_err_comps = 0;

    for (int i = 0; i < count; i++) {
        if (strcmp(entries[i].level, "ERROR") == 0) {
            int found = 0;
            for (int j = 0; j < num_err_comps; j++) {
                if (strcmp(err_comps[j], entries[i].component) == 0) {
                    err_counts[j]++;
                    found = 1;
                    break;
                }
            }
            if (!found) {
                err_comps[num_err_comps] = strdup(entries[i].component);
                err_counts[num_err_comps] = 1;
                num_err_comps++;
            }
        }
    }

    int max_ec = 0;
    for (int i = 1; i < num_err_comps; i++)
        if (err_counts[i] > err_counts[max_ec]) max_ec = i;

    /* Unique Error Messages */
    char **err_msgs = malloc((size_t)(count + 1) * sizeof(char *));
    int num_err_msgs = 0;

    for (int i = 0; i < count; i++) {
        if (strcmp(entries[i].level, "ERROR") == 0) {
            int found = 0;
            for (int j = 0; j < num_err_msgs; j++) {
                if (strcmp(err_msgs[j], entries[i].message) == 0) {
                    found = 1;
                    break;
                }
            }
            if (!found) {
                err_msgs[num_err_msgs] = strdup(entries[i].message);
                num_err_msgs++;
            }
        }
    }

    for (int i = 0; i < num_err_msgs; i++)
        for (int j = i + 1; j < num_err_msgs; j++)
            if (strcmp(err_msgs[i], err_msgs[j]) > 0) {
                char *t = err_msgs[i]; err_msgs[i] = err_msgs[j]; err_msgs[j] = t;
            }

    /* Busiest Hour */
    int hour_counts[24] = {0};
    for (int i = 0; i < count; i++)
        hour_counts[entries[i].hour]++;

    int busiest = 0;
    for (int i = 1; i < 24; i++)
        if (hour_counts[i] > hour_counts[busiest]) busiest = i;

    /* Output */
    printf("=== Log Analysis ===\n");
    printf("\n");
    printf("Entries by Level:\n");
    for (int i = 0; i < num_levels; i++)
        printf("  %s: %d\n", levels[level_idx[i]], level_counts[level_idx[i]]);
    printf("\n");
    printf("Component with Most Errors: %s (%d errors)\n", err_comps[max_ec], err_counts[max_ec]);
    printf("\n");
    printf("Unique Error Messages:\n");
    for (int i = 0; i < num_err_msgs; i++)
        printf("  - %s\n", err_msgs[i]);
    printf("\n");
    printf("Busiest Hour: %02d:00 (%d entries)\n", busiest, hour_counts[busiest]);

    free(entries);
    for (int i = 0; i < num_levels; i++) free(levels[i]);
    free(levels);
    free(level_counts);
    free(level_idx);
    for (int i = 0; i < num_err_comps; i++) free(err_comps[i]);
    free(err_comps);
    free(err_counts);
    for (int i = 0; i < num_err_msgs; i++) free(err_msgs[i]);
    free(err_msgs);

