public class Main {
    public static void main(String[] args) throws Exception {
        String path = "<tmp>";
        String json = new String(Files.readAllBytes(Paths.get(path)));

        List<String> nodes = new ArrayList<>();
        List<double[]> edges = new ArrayList<>();
        List<String> edgeFrom = new ArrayList<>();
        List<String> edgeTo = new ArrayList<>();

        // Parse nodes
        int nodesKeyIdx = json.indexOf("\"nodes\"");
        int bracketStart = json.indexOf('[', nodesKeyIdx);
        int bracketEnd = findMatchingBracket(json, bracketStart);
        String nodesStr = json.substring(bracketStart + 1, bracketEnd);
        for (String s : nodesStr.split(",")) {
            s = s.trim();
            if (s.startsWith("\"")) {
                s = s.substring(1, s.length() - 1);
                nodes.add(s);
            }
        }

        // Parse edges
        int edgesKeyIdx = json.indexOf("\"edges\"");
        bracketStart = json.indexOf('[', edgesKeyIdx);
        bracketEnd = findMatchingBracket(json, bracketStart);
        String edgesStr = json.substring(bracketStart + 1, bracketEnd);

        int pos = 0;
        while (pos < edgesStr.length()) {
            int objStart = edgesStr.indexOf('{', pos);
            if (objStart == -1) break;
            int objEnd = findMatchingBrace(edgesStr, objStart);
            String obj = edgesStr.substring(objStart, objEnd + 1);

            String from = extractStringValue(obj, "from");
            String to = extractStringValue(obj, "to");
            double weight = extractNumberValue(obj, "weight");

            edgeFrom.add(from);
            edgeTo.add(to);
            edges.add(new double[]{weight});

            pos = objEnd + 1;
        }

        // Build adjacency list
        Map<String, List<String[]>> adj = new LinkedHashMap<>();
        for (String n : nodes) {
            adj.put(n, new ArrayList<>());
        }
        for (int i = 0; i < edgeFrom.size(); i++) {
            String f = edgeFrom.get(i);
            String t = edgeTo.get(i);
            double w = edges.get(i)[0];
            adj.get(f).add(new String[]{t, String.valueOf(w)});
            adj.get(t).add(new String[]{f, String.valueOf(w)});
        }

        // Dijkstra's algorithm
        Map<String, Double> dist = new HashMap<>();
        for (String n : nodes) {
            dist.put(n, Double.MAX_VALUE);
        }
        dist.put("A", 0.0);

        PriorityQueue<double[]> pq = new PriorityQueue<>((a, b) -> Double.compare(a[0], b[0]));
        // We'll use a different approach: store (distance, node)
        PriorityQueue<Object[]> pq2 = new PriorityQueue<>((a, b) -> Double.compare((Double) a[0], (Double) b[0]));
        pq2.add(new Object[]{0.0, "A"});

        while (!pq2.isEmpty()) {
            Object[] curr = pq2.poll();
            double d = (Double) curr[0];
            String node = (String) curr[1];

            if (d > dist.get(node)) continue;

            for (String[] neighbor : adj.get(node)) {
                String nNode = neighbor[0];
                double w = Double.parseDouble(neighbor[1]);
                double newDist = d + w;
                if (newDist < dist.get(nNode)) {
                    dist.put(nNode, newDist);
                    pq2.add(new Object[]{newDist, nNode});
                }
            }
        }

        // Output
        List<String> sortedNodes = new ArrayList<>(nodes);
        Collections.sort(sortedNodes);

        System.out.println("=== Shortest Paths from A ===");
        System.out.println();
        for (String n : sortedNodes) {
            double d = dist.get(n);
            if (d == Double.MAX_VALUE) {
                System.out.println("A -> " + n + ": unreachable");
            } else if (d == Math.floor(d)) {
                System.out.println("A -> " + n + ": " + (long) d);
            } else {
                System.out.println("A -> " + n + ": " + d);
            }
        }
    }

    static int findMatchingBracket(String s, int start) {
        int depth = 0;
        for (int i = start; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '[') depth++;
            else if (c == ']') {
                depth--;
                if (depth == 0) return i;
            }
        }
        return s.length() - 1;
    }

    static int findMatchingBrace(String s, int start) {
        int depth = 0;
        for (int i = start; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '{') depth++;
            else if (c == '}') {
                depth--;
                if (depth == 0) return i;
            }
        }
        return s.length() - 1;
    }

    static String extractStringValue(String obj, String key) {
        int idx = obj.indexOf("\"" + key + "\"");
        int colonIdx = obj.indexOf(':', idx);
        int quoteStart = obj.indexOf('"', colonIdx);
        int quoteEnd = obj.indexOf('"', quoteStart + 1);
        return obj.substring(quoteStart + 1, quoteEnd);
    }

    static double extractNumberValue(String obj, String key) {
        int idx = obj.indexOf("\"" + key + "\"");
        int colonIdx = obj.indexOf(':', idx);
        int numStart = colonIdx + 1;
        while (numStart < obj.length() && (obj.charAt(numStart) == ' ' || obj.charAt(numStart) == '\t')) numStart++;
        int numEnd = numStart;
        while (numEnd < obj.length() && (Character.isDigit(obj.charAt(numEnd)) || obj.charAt(numEnd) == '-' || obj.charAt(numEnd) == '.' || obj.charAt(numEnd) == 'e' || obj.charAt(numEnd) == 'E' || obj.charAt(numEnd) == '+')) {
            numEnd++;
        }
        return Double.parseDouble(obj.substring(numStart, numEnd));
    }
