use std::collections::BTreeMap;
use std::fs;

#[derive(Debug, Clone, PartialEq)]
enum Json {
    Object(BTreeMap<String, Json>),
    Array(Vec<Json>),
    String(String),
    Number(f64),
    Bool(bool),
    Null,
}

struct Parser {
    chars: Vec<char>,
    pos: usize,
}

impl Parser {
    fn new(s: &str) -> Self {
        Parser { chars: s.chars().collect(), pos: 0 }
    }

    fn peek(&self) -> Option<char> {
        self.chars.get(self.pos).copied()
    }

    fn next(&mut self) -> Option<char> {
        let c = self.chars.get(self.pos).copied();
        if c.is_some() {
            self.pos += 1;
        }
        c
    }

    fn skip_whitespace(&mut self) {
        while let Some(c) = self.peek() {
            if c == ' ' || c == '\t' || c == '\n' || c == '\r' {
                self.pos += 1;
            } else {
                break;
            }
        }
    }

    fn parse_value(&mut self) -> Json {
        self.skip_whitespace();
        match self.peek() {
            Some('{') => self.parse_object(),
            Some('[') => self.parse_array(),
            Some('"') => Json::String(self.parse_string()),
            Some('t') => {
                self.parse_literal("true");
                Json::Bool(true)
            }
            Some('f') => {
                self.parse_literal("false");
                Json::Bool(false)
            }
            Some('n') => {
                self.parse_literal("null");
                Json::Null
            }
            _ => self.parse_number(),
        }
    }

    fn parse_literal(&mut self, literal: &str) {
        for _ in literal.chars() {
            self.next();
        }
    }

    fn parse_object(&mut self) -> Json {
        self.next(); // {
        let mut map = BTreeMap::new();
        self.skip_whitespace();
        if self.peek() == Some('}') {
            self.next();
            return Json::Object(map);
        }
        loop {
            self.skip_whitespace();
            let key = self.parse_string();
            self.skip_whitespace();
            self.next(); // :
            let value = self.parse_value();
            map.insert(key, value);
            self.skip_whitespace();
            match self.next() {
                Some(',') => continue,
                Some('}') => break,
                _ => panic!("Expected ',' or '}' in object"),
            }
        }
        Json::Object(map)
    }

    fn parse_array(&mut self) -> Json {
        self.next(); // [
        let mut arr = Vec::new();
        self.skip_whitespace();
        if self.peek() == Some(']') {
            self.next();
            return Json::Array(arr);
        }
        loop {
            let value = self.parse_value();
            arr.push(value);
            self.skip_whitespace();
            match self.next() {
                Some(',') => continue,
                Some(']') => break,
                _ => panic!("Expected ',' or ']' in array"),
            }
        }
        Json::Array(arr)
    }

    fn parse_string(&mut self) -> String {
        self.next(); // "
        let mut s = String::new();
        loop {
            match self.next() {
                Some('"') => break,
                Some('\\') => {
                    match self.next() {
                        Some('"') => s.push('"'),
                        Some('\\') => s.push('\\'),
                        Some('/') => s.push('/'),
                        Some('b') => s.push('\u{0008}'),
                        Some('f') => s.push('\u{000C}'),
                        Some('n') => s.push('\n'),
                        Some('r') => s.push('\r'),
                        Some('t') => s.push('\t'),
                        Some('u') => {
                            let mut code = 0u32;
                            for _ in 0..4 {
                                let c = self.next().unwrap();
                                code = code * 16 + c.to_digit(16).unwrap();
                            }
                            if (0xD800..=0xDBFF).contains(&code) {
                                if self.peek() == Some('\\') {
                                    self.next();
                                    if self.peek() == Some('u') {
                                        self.next();
                                        let mut low = 0u32;
                                        for _ in 0..4 {
                                            let c = self.next().unwrap();
                                            low = low * 16 + c.to_digit(16).unwrap();
                                        }
                                        code = 0x10000 + ((code - 0xD800) << 10) + (low - 0xDC00);
                                    }
                                }
                            }
                            s.push(char::from_u32(code).unwrap_or('\u{FFFD}'));
                        }
                        _ => panic!("Invalid escape sequence"),
                    }
                }
                Some(c) => s.push(c),
                None => panic!("Unterminated string"),
            }
        }
        s
    }

    fn parse_number(&mut self) -> Json {
        let start = self.pos;
        if self.peek() == Some('-') {
            self.next();
        }
        while let Some(c) = self.peek() {
            if c.is_ascii_digit() {
                self.next();
            } else {
                break;
            }
        }
        if self.peek() == Some('.') {
            self.next();
            while let Some(c) = self.peek() {
                if c.is_ascii_digit() {
                    self.next();
                } else {
                    break;
                }
            }
        }
        if self.peek() == Some('e') || self.peek() == Some('E') {
            self.next();
            if self.peek() == Some('+') || self.peek() == Some('-') {
                self.next();
            }
            while let Some(c) = self.peek() {
                if c.is_ascii_digit() {
                    self.next();
                } else {
                    break;
                }
            }
        }
        let s: String = self.chars[start..self.pos].iter().collect();
        let n: f64 = s.parse().unwrap();
        Json::Number(n)
    }
}

fn deep_merge(a: &Json, b: &Json) -> Json {
    match (a, b) {
        (Json::Object(a_map), Json::Object(b_map)) => {
            let mut result = BTreeMap::new();
            for (k, v) in a_map {
                result.insert(k.clone(), v.clone());
            }
            for (k, v) in b_map {
                if let Some(existing) = result.get(k) {
                    result.insert(k.clone(), deep_merge(existing, v));
                } else {
                    result.insert(k.clone(), v.clone());
                }
            }
            Json::Object(result)
        }
        (Json::Array(a_arr), Json::Array(b_arr)) => {
            let mut result: Vec<Json> = a_arr.clone();
            for item in b_arr {
                if !result.contains(item) {
                    result.push(item.clone());
                }
            }
            Json::Array(result)
        }
        _ => b.clone(),
    }
}

fn escape_string(s: &str) -> String {
    let mut result = String::new();
    for c in s.chars() {
        match c {
            '"' => result.push_str("\\\""),
            '\\' => result.push_str("\\\\"),
            '\n' => result.push_str("\\n"),
            '\r' => result.push_str("\\r"),
            '\t' => result.push_str("\\t"),
            '\u{0008}' => result.push_str("\\b"),
            '\u{000C}' => result.push_str("\\f"),
            c if (c as u32) < 0x20 => {
                result.push_str(&format!("\\u{:04x}", c as u32));
            }
            c => result.push(c),
        }
    }
    result
}

fn format_number(n: f64) -> String {
    if n.fract() == 0.0 && n.abs() < 1e15 {
        format!("{}", n as i64)
    } else {
        format!("{}", n)
    }
}

fn serialize(value: &Json, indent: usize) -> String {
    let pad = "  ".repeat(indent);
    let pad_inner = "  ".repeat(indent + 1);
    match value {
        Json::Null => "null".to_string(),
        Json::Bool(b) => b.to_string(),
        Json::String(s) => format!("\"{}\"", escape_string(s)),
        Json::Number(n) => format_number(*n),
        Json::Array(arr) => {
            if arr.is_empty() {
                return "[]".to_string();
            }
            let items: Vec<String> = arr
                .iter()
                .map(|v| format!("{}{}", pad_inner, serialize(v, indent + 1)))
                .collect();
            format!("[\n{}\n{}]", items.join(",\n"), pad)
        }
        Json::Object(map) => {
            if map.is_empty() {
                return "{}".to_string();
            }
            let items: Vec<String> = map
                .iter()
                .map(|(k, v)| {
                    format!(
                        "{}\"{}\": {}",
                        pad_inner,
                        escape_string(k),
                        serialize(v, indent + 1)
                    )
                })
                .collect();
            format!("{{\n{}\n{}}}", items.join(",\n"), pad)
        }
    }
}

fn main() {
    let a_str = fs::read_to_string(
        "<tmp>",
    )
    .expect("Failed to read config_a.json");
    let b_str = fs::read_to_string(
        "<tmp>",
    )
    .expect("Failed to read config_b.json");

    let a = Parser::new(&a_str).parse_value();
    let b = Parser::new(&b_str).parse_value();

    let merged = deep_merge(&a, &b);

    println!("{}", serialize(&merged, 0));
}
