static char *run_cmd(const char *cmd)
{
    FILE *fp = popen(cmd, "r");
    if (!fp)
        return NULL;

    size_t cap = 4096;
    size_t len = 0;
    char *buf = (char *)malloc(cap);
    if (!buf) {
        pclose(fp);
        return NULL;
    }

    int c;
    while ((c = fgetc(fp)) != EOF) {
        if (len + 1 >= cap) {
            cap *= 2;
            char *tmp = (char *)realloc(buf, cap);
            if (!tmp) {
                free(buf);
                pclose(fp);
                return NULL;
            }
            buf = tmp;
        }
        buf[len++] = (char)c;
    }
    pclose(fp);
    buf[len] = '\0';

    /* strip trailing whitespace */
    while (len > 0 && isspace((unsigned char)buf[len - 1]))
        buf[--len] = '\0';

    return buf;
}

int main(void)
{
    char *os = run_cmd("uname -s");
    char *arch = run_cmd("uname -m");
    char *user = run_cmd("whoami");
    char *host = run_cmd("hostname");

    if (!os || !arch || !user || !host) {
        fprintf(stderr, "error: failed to run command\n");
        free(os);
        free(arch);
        free(user);
