public class Main {
    static class FileEntry {
        String relPath;
        int lines;
        int chars;
        FileEntry(String relPath, int lines, int chars) {
            this.relPath = relPath;
            this.lines = lines;
            this.chars = chars;
        }
    }

    private static int countLines(byte[] bytes) {
        if (bytes.length == 0) return 0;
        int count = 0;
        for (byte b : bytes) {
            if (b == '\n') count++;
        }
        if (bytes[bytes.length - 1] != '\n') {
            count++;
        }
        return count;
    }

    public static void main(String[] args) throws Exception {
        Path root = Paths.get("<tmp>");

        Map<String, List<FileEntry>> extensionMap = new TreeMap<>();

        Files.walkFileTree(root, new SimpleFileVisitor<Path>() {
            @Override
            public FileVisitResult visitFile(Path file, BasicFileAttributes attrs) throws IOException {
                if (Files.isSymbolicLink(file)) {
                    return FileVisitResult.CONTINUE;
                }

                Path relativePath = root.relativize(file);
                String relPath = relativePath.toString().replace('\\', '/');

                String fileName = file.getFileName().toString();
                String extension = "";
                int lastDot = fileName.lastIndexOf('.');
                if (lastDot > 0) {
                    extension = fileName.substring(lastDot);
                }

                byte[] bytes = Files.readAllBytes(file);
                int chars = bytes.length;
                int lines = countLines(bytes);

                extensionMap.computeIfAbsent(extension, k -> new ArrayList<>())
                        .add(new FileEntry(relPath, lines, chars));

                return FileVisitResult.CONTINUE;
            }

            @Override
            public FileVisitResult visitFileFailed(Path file, IOException exc) {
                return FileVisitResult.CONTINUE;
            }
        });

        StringBuilder sb = new StringBuilder();
