                Json::Num(0) // true, unlikely needed
            }
            Some(b'f') => {
                self.pos += 5;
                Json::Num(0) // false, unlikely needed
            }
            Some(b'n') => {
                self.pos += 4;
                Json::Num(0) // null, unlikely needed
            }
            _ => Json::Num(self.parse_number()),
        }
    }

    fn parse_object(&mut self) -> Json {
        self.expect(b'{');
        let mut entries = Vec::new();
        self.skip_ws();
        if self.peek() == Some(b'}') {
            self.pos += 1;
            return Json::Obj(entries);
        }
        loop {
            self.skip_ws();
            let key = self.parse_string();
            self.expect(b':');
            let val = self.parse_value();
            entries.push((key, val));
            self.skip_ws();
            match self.peek() {
                Some(b',') => {
                    self.pos += 1;
                }
                Some(b'}') => {
                    self.pos += 1;
                    break;
                }
                _ => break,
            }
        }
        Json::Obj(entries)
    }

    fn parse_array(&mut self) -> Json {
        self.expect(b'[');
        let mut items = Vec::new();
        self.skip_ws();
        if self.peek() == Some(b']') {
            self.pos += 1;
            return Json::Arr(items);
        }
        loop {
            let val = self.parse_value();
            items.push(val);
            self.skip_ws();
            match self.peek() {
                Some(b',') => {
                    self.pos += 1;
                }
                Some(b']') => {
                    self.pos += 1;
                    break;
                }
                _ => break,
            }
        }
        Json::Arr(items)
    }
}

struct Edge {
    from: String,
    to: String,
    weight: i64,
}

fn main() {
    let content = fs::read_to_string(
        "<tmp>",
    )
    .expect("Failed to read file");

    let mut parser = Parser::new(&content);
    let json = parser.parse_value();

    let mut nodes: Vec<String> = Vec::new();
    let mut edges: Vec<Edge> = Vec::new();

    if let Json::Obj(entries) = &json {
        for (key, val) in entries {
            if key == "nodes" {
                if let Json::Arr(items) = val {
                    for item in items {
                        if let Json::Str(s) = item {
                            nodes.push(s.clone());
                        }
                    }
                }
            } else if key == "edges" {
                if let Json::Arr(items) = val {
                    for item in items {
                        if let Json::Obj(e_entries) = item {
                            let mut from = String::new();
                            let mut to = String::new();
                            let mut weight = 0i64;
                            for (k, v) in e_entries {
                                match k.as_str() {
                                    "from" => {
                                        if let Json::Str(s) = v {
                                            from = s.clone();
                                        }
                                    }
                                    "to" => {
                                        if let Json::Str(s) = v {
                                            to = s.clone();
                                        }
                                    }
                                    "weight" => {
                                        if let Json::Num(n) = v {
                                            weight = *n;
                                        }
                                    }
                                    _ => {}
                                }
                            }
                            edges.push(Edge { from, to, weight });
                        }
                    }
                }
            }
        }
    }

    // Build adjacency list (undirected)
    let mut adj: HashMap<String, Vec<(String, i64)>> = HashMap::new();
    for node in &nodes {
        adj.entry(node.clone()).or_insert_with(Vec::new);
    }
    for edge in &edges {
        adj.entry(edge.from.clone())
            .or_insert_with(Vec::new)
            .push((edge.to.clone(), edge.weight));
        adj.entry(edge.to.clone())
            .or_insert_with(Vec::new)
            .push((edge.from.clone(), edge.weight));
    }

    // Dijkstra's algorithm
    let mut dist: HashMap<String, i64> = HashMap::new();
    for node in &nodes {
        dist.insert(node.clone(), i64::MAX);
    }
    dist.insert("A".to_string(), 0);

    let mut visited: HashMap<String, bool> = HashMap::new();
    for node in &nodes {
        visited.insert(node.clone(), false);
    }

    for _ in 0..nodes.len() {
        // Find unvisited node with minimum distance
        let mut min_node: Option<String> = None;
        let mut min_dist = i64::MAX;
        for node in &nodes {
            if !visited[node] && dist[node] < min_dist {
                min_dist = dist[node];
                min_node = Some(node.clone());
            }
        }

        let u = match min_node {
            Some(n) => n,
            None => break,
        };

        visited.insert(u.clone(), true);

        // Relax edges
        if let Some(neighbors) = adj.get(&u) {
            for (v, w) in neighbors {
                let new_dist = dist[&u] + w;
                if new_dist < dist[v] {
                    dist.insert(v.clone(), new_dist);
                }
            }
        }
    }

    // Output
    println!("=== Shortest Paths from A ===");
    println!();

    let mut sorted_nodes: Vec<&String> = nodes.iter().collect();
    sorted_nodes.sort();

    for node in sorted_nodes {
        let d = dist[node];
        if d == i64::MAX {
            println!("A -> {}: unreachable", node);
        } else {
            println!("A -> {}: {}", node, d);
        }
    }
}
