import * as fs from 'fs';
import * as path from 'path';

const rootDir = '<tmp>';

interface FileInfo {
  relativePath: string;
  lines: number;
  chars: number;
}

function walk(dir: string, root: string, visited: Set<string>): FileInfo[] {
  const results: FileInfo[] = [];

  let entries: fs.Dirent[];
  try {
    entries = fs.readdirSync(dir, { withFileTypes: true });
  } catch {
    return results;
  }

  for (const entry of entries) {
    const fullPath = path.join(dir, entry.name);

    if (entry.isSymbolicLink()) {
      continue;
    }

    if (entry.isDirectory()) {
      let realPath: string;
      try {
        realPath = fs.realpathSync(fullPath);
      } catch {
        continue;
      }
      if (visited.has(realPath)) continue;
      visited.add(realPath);

      results.push(...walk(fullPath, root, visited));
    } else if (entry.isFile()) {
      let content: Buffer;
      try {
        content = fs.readFileSync(fullPath);
      } catch {
        continue;
      }
      const chars = content.length;
      const contentStr = content.toString('utf-8');
      let lines: number;
      if (contentStr.length === 0) {
        lines = 0;
      } else {
        lines = contentStr.split('\n').length;
        if (contentStr.endsWith('\n')) lines--;
      }

      const relativePath = path.relative(root, fullPath).replace(/\\/g, '/');
      results.push({ relativePath, lines, chars });
    }
  }

  return results;
}

function main(): void {
  const visited = new Set<string>();
  try {
    visited.add(fs.realpathSync(rootDir));
  } catch {
    visited.add(rootDir);
  }

  const allFiles = walk(rootDir, rootDir, visited);

  const groups = new Map<string, FileInfo[]>();
  for (const file of allFiles) {
    const ext = path.extname(file.relativePath);
    if (!groups.has(ext)) groups.set(ext, []);
    groups.get(ext)!.push(file);
  }

  const sortedExts = Array.from(groups.keys()).sort();

  for (const ext of sortedExts) {
    groups.get(ext)!.sort((a, b) => a.relativePath.localeCompare(b.relativePath));
  }

  const output: string[] = [];
  output.push('=== File Tree Analysis ===');
  output.push('');

  let totalFiles = 0;
  let totalLines = 0;
  let totalChars = 0;

  for (const ext of sortedExts) {
    const files = groups.get(ext)!;
    const extLines = files.reduce((s, f) => s + f.lines, 0);
    const extChars = files.reduce((s, f) => s + f.chars, 0);

    totalFiles += files.length;
    totalLines += extLines;
    totalChars += extChars;

    output.push(`Extension: ${ext}`);
    output.push(`  Files: ${files.length}`);
    output.push(`  Total Lines: ${extLines}`);
    output.push(`  Total Characters: ${extChars}`);
    for (const f of files) {
      output.push(`    ${f.relativePath}: ${f.lines} lines, ${f.chars} chars`);
    }
  }

  output.push('');
  output.push(`Total: ${totalFiles} files, ${totalLines} lines, ${totalChars} characters`);

  process.stdout.write(output.join('\n') + '\n');
}

main();

