static FileEntry *entries = NULL;
static int entry_count = 0;
static int entry_cap = 0;

static void add_entry(const char *relpath, const char *ext, long lines, long chars) {
    if (entry_count >= entry_cap) {
        entry_cap = entry_cap ? entry_cap * 2 : 128;
        FileEntry *tmp = realloc(entries, (size_t)entry_cap * sizeof(FileEntry));
        if (!tmp) { fprintf(stderr, "OOM\n"); exit(1); }
        entries = tmp;
    }
    entries[entry_count].relpath = strdup(relpath);
    entries[entry_count].ext = strdup(ext);
    entries[entry_count].lines = lines;
    entries[entry_count].chars = chars;
    entry_count++;
}

static void count_file(const char *path, long *lines, long *chars) {
    FILE *f = fopen(path, "rb");
    if (!f) { *lines = 0; *chars = 0; return; }
    long c = 0;
    long nl = 0;
    int last_char = -1;
    int ch;
    while ((ch = fgetc(f)) != EOF) {
        c++;
        if (ch == '\n') nl++;
        last_char = ch;
    }
    fclose(f);
    *chars = c;
    if (c == 0) {
        *lines = 0;
    } else {
        *lines = nl;
        if (last_char != '\n') *lines++;
    }
}

static void walk(const char *dir, const char *relprefix) {
    DIR *d = opendir(dir);
    if (!d) return;

    struct dirent *de;
    while ((de = readdir(d)) != NULL) {
        if (strcmp(de->d_name, ".") == 0 || strcmp(de->d_name, "..") == 0)
            continue;

        char fullpath[4096];
        snprintf(fullpath, sizeof(fullpath), "%s/%s", dir, de->d_name);

        char relpath[4096];
        if (relprefix[0] == '\0')
            snprintf(relpath, sizeof(relpath), "%s", de->d_name);
        else
            snprintf(relpath, sizeof(relpath), "%s/%s", relprefix, de->d_name);

        struct stat st;
        if (lstat(fullpath, &st) != 0) continue;

        if (S_ISLNK(st.st_mode)) continue;

        if (S_ISDIR(st.st_mode)) {
            walk(fullpath, relpath);
        } else if (S_ISREG(st.st_mode)) {
            const char *base = de->d_name;
            const char *dot = strrchr(base, '.');
            char ext[512] = "";
