use std::collections::BTreeMap;
use std::fs;
use std::io::Read;
use std::path::Path;

struct FileEntry {
    rel_path: String,
    lines: u64,
    chars: u64,
}

fn count_lines_and_bytes(path: &Path) -> Option<(u64, u64)> {
    let mut file = fs::File::open(path).ok()?;
    let mut buf = [0u8; 8192];
    let mut lines: u64 = 0;
    let mut bytes: u64 = 0;
    let mut last_byte_was_newline = false;
    let mut any_data = false;

    loop {
        let n = match file.read(&mut buf) {
            Ok(n) => n,
            Err(_) => break,
        };
        if n == 0 {
            break;
        }
        bytes += n as u64;
        any_data = true;
        for &b in &buf[..n] {
            if b == b'\n' {
                lines += 1;
                last_byte_was_newline = true;
            } else {
                last_byte_was_newline = false;
            }
        }
    }

    if any_data && !last_byte_was_newline {
        lines += 1;
    }

    Some((lines, bytes))
}

fn walk_dir(dir: &Path, base: &Path, files: &mut Vec<FileEntry>) {
    let entries = match fs::read_dir(dir) {
        Ok(e) => e,
        Err(_) => return,
    };

    for entry in entries.flatten() {
        let path = entry.path();

        if path
            .symlink_metadata()
            .map(|m| m.file_type().is_symlink())
            .unwrap_or(false)
        {
            continue;
        }

        let metadata = match fs::metadata(&path) {
            Ok(m) => m,
            Err(_) => continue,
        };

        if metadata.is_dir() {
            walk_dir(&path, base, files);
        } else if metadata.is_file() {
            let rel = match path.strip_prefix(base) {
                Ok(r) => r,
                Err(_) => continue,
            };
            let rel_str = rel.to_string_lossy().replace('\\', "/");

            if let Some((lines, chars)) = count_lines_and_bytes(&path) {
                files.push(FileEntry {
                    rel_path: rel_str,
                    lines,
                    chars,
                });
            }
        }
    }
}

fn main() {
    let base = Path::new(
        "<tmp>",
    );

    let mut files: Vec<FileEntry> = Vec::new();
    walk_dir(base, base, &mut files);

    let mut groups: BTreeMap<String, Vec<&FileEntry>> = BTreeMap::new();

    for f in &files {
        let path = Path::new(&f.rel_path);
        let ext = path
            .extension()
            .map(|e| format!(".{}", e.to_string_lossy()))
