import Foundation

let baseDir = "<tmp>"
let fileManager = FileManager.default

struct FileEntry {
    let relativePath: String
    let lines: Int
    let chars: Int
}

var filesByExt: [String: [FileEntry]] = [:]
var visitedInodes: Set<UInt64> = []

func walkDirectory(_ path: String) {
    var dirStat = stat()
    guard stat(path, &dirStat) == 0 else { return }
    let inode = dirStat.st_ino
    if visitedInodes.contains(inode) { return }
    visitedInodes.insert(inode)

    guard let contents = try? fileManager.contentsOfDirectory(atPath: path) else { return }

    for name in contents {
        let fullPath = path + "/" + name

        var lstatBuf = stat()
        guard lstat(fullPath, &lstatBuf) == 0 else { continue }

        let fileType = lstatBuf.st_mode & S_IFMT
        if fileType == S_IFLNK {
            continue
        }

        if fileType == S_IFDIR {
            walkDirectory(fullPath)
        } else if fileType == S_IFREG {
            let data: Data
            if let fileData = try? Data(contentsOf: URL(fileURLWithPath: fullPath)) {
                data = fileData
            } else {
                data = Data()
            }

            let chars = data.count
            let content = String(data: data, encoding: .utf8) ?? ""

            let lines: Int
            if content.isEmpty {
                lines = 0
            } else {
                var lineCount = 0
                var inLine = false
                for ch in content {
                    if ch == "\n" {
                        lineCount += 1
                        inLine = false
                    } else {
                        if !inLine {
                            inLine = true
                        }
                    }
                }
                if inLine {
                    lineCount += 1
                }
                lines = lineCount
            }

            let relPath = String(fullPath.dropFirst(baseDir.count + 1))
            let ext = (name as NSString).pathExtension
            let extKey = "." + ext

            let entry = FileEntry(relativePath: relPath, lines: lines, chars: chars)
            filesByExt[extKey, default: []].append(entry)
        }
    }
}

walkDirectory(baseDir)

print("=== File Tree Analysis ===")
print("")

let sortedExts = filesByExt.keys.sorted()

for ext in sortedExts {
    let entries = filesByExt[ext]!
