fn extract_body(response: &str) -> String {
    let (body_start, is_chunked) = if let Some(pos) = response.find("\r\n\r\n") {
        let header = &response[..pos];
        let chunked = header.to_lowercase().contains("transfer-encoding: chunked");
        (pos + 4, chunked)
    } else if let Some(pos) = response.find("\n\n") {
        let header = &response[..pos];
        let chunked = header.to_lowercase().contains("transfer-encoding: chunked");
        (pos + 2, chunked)
    } else {
        (0, false)
    };
    let body = &response[body_start..];
    if is_chunked {
        decode_chunked(body)
    } else {
        body.to_string()
    }
}

fn decode_chunked(data: &str) -> String {
    let mut result = String::new();
    let mut remaining = data;
    while !remaining.is_empty() {
        let nl = remaining.find('\n').unwrap_or(remaining.len());
        let size_str = remaining[..nl].trim().trim_end_matches('\r');
        let size = u64::from_str_radix(size_str, 16).unwrap_or(0);
        if size == 0 {
            break;
        }
        let data_start = nl + 1;
        if data_start >= remaining.len() {
            break;
        }
        let data_end = data_start + size as usize;
        if data_end > remaining.len() {
            break;
        }
        result.push_str(&remaining[data_start..data_end]);
        remaining = &remaining[data_end..];
        if remaining.starts_with("\r\n") {
            remaining = &remaining[2..];
        } else if remaining.starts_with('\n') {
            remaining = &remaining[1..];
        }
    }
    result
}

fn parse_json_array(s: &str) -> Vec<Product> {
    let bytes = s.as_bytes();
    let mut products = Vec::new();
    let mut i = 0;
    while i < bytes.len() {
        if bytes[i] == b'{' {
            let mut depth: i32 = 0;
            let mut j = i;
            while j < bytes.len() {
                if bytes[j] == b'{' {
                    depth += 1;
                }
                if bytes[j] == b'}' {
                    depth -= 1;
                }
                if depth == 0 {
                    break;
                }
                j += 1;
            }
            let obj_str = &s[i..=j];
            products.push(parse_object(obj_str));
            i = j + 1;
        } else {
            i += 1;
        }
    }
    products
}

fn parse_object(s: &str) -> Product {
    let name = extract_string(s, "name");
    let price = extract_number(s, "price");
    Product { name, price }
}

fn extract_string(s: &str, key: &str) -> String {
    let pattern = format!("\"{}\"", key);
    let key_pos = s.find(&pattern).expect("key not found");
    let colon_pos = s.find(':', key_pos + pattern.len()).expect("colon not found");
    let bytes = s.as_bytes();
    let mut i = colon_pos + 1;
    while i < bytes.len() && bytes[i] != b'"' {
        i += 1;
    }
    i += 1;
    let start = i;
    while i < bytes.len() && bytes[i] != b'"' {
        i += 1;
    }
    s[start..i].to_string()
}

fn extract_number(s: &str, key: &str) -> f64 {
    let pattern = format!("\"{}\"", key);
    let key_pos = s.find(&pattern).expect("key not found");
    let colon_pos = s.find(':', key_pos + pattern.len()).expect("colon not found");
    let bytes = s.as_bytes();
    let mut i = colon_pos + 1;
    while i < bytes.len() && (bytes[i] == b' ' || bytes[i] == b'\t') {
        i += 1;
    }
    let start = i;
    while i < bytes.len()
        && (bytes[i].is_ascii_digit()
            || bytes[i] == b'.'
            || bytes[i] == b'-'
            || bytes[i] == b'+'
            || bytes[i] == b'e'
            || bytes[i] == b'E')
    {
        i += 1;
    }
    s[start..i].trim().parse::<f64>().expect("invalid number")
}

