            } else {
                result.append(Character(scalar))
            }
        }
    }
    return result
}

func formatNumber(_ num: NSNumber) -> String {
    if CFGetTypeID(num) == CFBooleanGetTypeID() {
        return num.boolValue ? "true" : "false"
    }
    let doubleVal = num.doubleValue
    if doubleVal == floor(doubleVal) && abs(doubleVal) < 9007199254740993.0 {
        return String(Int64(doubleVal))
    }
    return String(doubleVal)
}

func serialize(_ value: Any, indent: Int) -> String {
    let padding = String(repeating: " ", count: indent)
    let innerPadding = String(repeating: " ", count: indent + 2)

    if isDictionary(value) {
        let dict = value as! [String: Any]
        let keys = dict.keys.sorted()

        if keys.isEmpty {
            return "{}"
        }

        var lines: [String] = ["{"]
        for (i, key) in keys.enumerated() {
            let valStr = serialize(dict[key]!, indent: indent + 2)
            let comma = i < keys.count - 1 ? "," : ""
            lines.append(innerPadding + "\"" + escapeString(key) + "\": " + valStr + comma)
        }
        lines.append(padding + "}")
        return lines.joined(separator: "\n")
    }

    if isArray(value) {
        let arr = value as! [Any]
        if arr.isEmpty {
            return "[]"
        }

        var lines: [String] = ["["]
        for (i, item) in arr.enumerated() {
            let valStr = serialize(item, indent: indent + 2)
            let comma = i < arr.count - 1 ? "," : ""
            lines.append(innerPadding + valStr + comma)
        }
        lines.append(padding + "]")
        return lines.joined(separator: "\n")
    }

    if let str = value as? String {
        return "\"" + escapeString(str) + "\""
    }

    if let num = value as? NSNumber {
        return formatNumber(num)
    }

    if value is NSNull {
        return "null"
    }

    return "null"
}

