static json_value *parse_object(parser *p) {
    p->pos++;
    json_value *v = json_new(JSON_OBJECT);
    v->object.cap = 8;
    v->object.keys = xmalloc(sizeof(char *) * v->object.cap);
    v->object.values = xmalloc(sizeof(json_value *) * v->object.cap);
    v->object.count = 0;

    skip_ws(p);
    if (p->pos < p->len && p->buf[p->pos] == '}') {
        p->pos++;
        return v;
    }
    while (1) {
        skip_ws(p);
        char *key = parse_string_raw(p);
        skip_ws(p);
        if (p->pos >= p->len || p->buf[p->pos] != ':') { free(key); break; }
        p->pos++;
        skip_ws(p);
        json_value *val = parse_value(p);
