        } else if (p->pos < p->len && p->buf[p->pos] == '}') {
            p->pos++;
            break;
        } else {
            break;
        }
    }
    return v;
}

static json_value *parse_value(parser *p) {
    skip_ws(p);
    if (p->pos >= p->len) return json_new(JSON_NULL);
    char c = p->buf[p->pos];
    if (c == '{') return parse_object(p);
    if (c == '[') return parse_array(p);
    if (c == '"') {
        char *s = parse_string_raw(p);
        json_value *v = json_new(JSON_STRING);
        v->string_val = s;
        return v;
    }
    if (c == 't') {
        p->pos += 4;
        json_value *v = json_new(JSON_BOOL);
        v->bool_val = 1;
        return v;
    }
    if (c == 'f') {
        p->pos += 5;
        json_value *v = json_new(JSON_BOOL);
        v->bool_val = 0;
        return v;
    }
    if (c == 'n') {
        p->pos += 4;
        return json_new(JSON_NULL);
    }
    return parse_number(p);
}

static int json_equal(const json_value *a, const json_value *b) {
    if (a->type != b->type) return 0;
    switch (a->type) {
        case JSON_NULL: return 1;
        case JSON_BOOL: return a->bool_val == b->bool_val;
        case JSON_NUMBER: return a->number_val == b->number_val;
        case JSON_STRING: return strcmp(a->string_val, b->string_val) == 0;
        case JSON_ARRAY:
            if (a->array.count != b->array.count) return 0;
            for (int i = 0; i < a->array.count; i++)
                if (!json_equal(a->array.items[i], b->array.items[i])) return 0;
            return 1;
        case JSON_OBJECT:
            if (a->object.count != b->object.count) return 0;
            for (int i = 0; i < a->object.count; i++) {
                int found = 0;
                for (int j = 0; j < b->object.count; j++) {
                    if (strcmp(a->object.keys[i], b->object.keys[j]) == 0) {
                        if (!json_equal(a->object.values[i], b->object.values[j])) return 0;
                        found = 1;
                        break;
                    }
                }
                if (!found) return 0;
            }
            return 1;
    }
    return 0;
}

static int array_contains(const json_value *arr, const json_value *item) {
    for (int i = 0; i < arr->array.count; i++) {
        if (json_equal(arr->array.items[i], item)) return 1;
    }
    return 0;
}

static json_value *deep_copy(const json_value *v) {
    json_value *c = xmalloc(sizeof(json_value));
    c->type = v->type;
    switch (v->type) {
        case JSON_NULL: break;
        case JSON_BOOL: c->bool_val = v->bool_val; break;
        case JSON_NUMBER: c->number_val = v->number_val; break;
        case JSON_STRING: c->string_val = xstrdup(v->string_val); break;
        case JSON_ARRAY:
            c->array.count = v->array.count;
            c->array.cap = v->array.count > 0 ? v->array.count : 1;
            c->array.items = xmalloc(sizeof(json_value *) * c->array.cap);
            for (int i = 0; i < v->array.count; i++)
                c->array.items[i] = deep_copy(v->array.items[i]);
            break;
        case JSON_OBJECT:
            c->object.count = v->object.count;
            c->object.cap = v->object.count > 0 ? v->object.count : 1;
            c->object.keys = xmalloc(sizeof(char *) * c->object.cap);
            c->object.values = xmalloc(sizeof(json_value *) * c->object.cap);
            for (int i = 0; i < v->object.count; i++) {
                c->object.keys[i] = xstrdup(v->object.keys[i]);
                c->object.values[i] = deep_copy(v->object.values[i]);
            }
            break;
    }
    return c;
}

static json_value *merge_values(const json_value *a, const json_value *b) {
    if (a->type == JSON_OBJECT && b->type == JSON_OBJECT) {
        json_value *result = json_new(JSON_OBJECT);
        result->object.cap = a->object.count + b->object.count + 4;
        result->object.keys = xmalloc(sizeof(char *) * result->object.cap);
        result->object.values = xmalloc(sizeof(json_value *) * result->object.cap);
        result->object.count = 0;

        for (int i = 0; i < a->object.count; i++) {
            int found_in_b = -1;
            for (int j = 0; j < b->object.count; j++) {
                if (strcmp(a->object.keys[i], b->object.keys[j]) == 0) {
                    found_in_b = j;
                    break;
                }
            }
            if (result->object.count >= result->object.cap) {
                result->object.cap *= 2;
                result->object.keys = xrealloc(result->object.keys, sizeof(char *) * result->object.cap);
                result->object.values = xrealloc(result->object.values, sizeof(json_value *) * result->object.cap);
            }
            result->object.keys[result->object.count] = xstrdup(a->object.keys[i]);
            if (found_in_b >= 0) {
                result->object.values[result->object.count] = merge_values(a->object.values[i], b->object.values[found_in_b]);
            } else {
                result->object.values[result->object.count] = deep_copy(a->object.values[i]);
            }
            result->object.count++;
        }

        for (int j = 0; j < b->object.count; j++) {
            int found_in_a = 0;
            for (int i = 0; i < a->object.count; i++) {
                if (strcmp(b->object.keys[j], a->object.keys[i]) == 0) {
                    found_in_a = 1;
                    break;
                }
            }
            if (!found_in_a) {
                if (result->object.count >= result->object.cap) {
                    result->object.cap *= 2;
                    result->object.keys = xrealloc(result->object.keys, sizeof(char *) * result->object.cap);
                    result->object.values = xrealloc(result->object.values, sizeof(json_value *) * result->object.cap);
                }
                result->object.keys[result->object.count] = xstrdup(b->object.keys[j]);
                result->object.values[result->object.count] = deep_copy(b->object.values[j]);
                result->object.count++;
            }
        }
        return result;
    }

    if (a->type == JSON_ARRAY && b->type == JSON_ARRAY) {
        json_value *result = json_new(JSON_ARRAY);
        result->array.cap = a->array.count + b->array.count + 4;
        result->array.items = xmalloc(sizeof(json_value *) * result->array.cap);
        result->array.count = 0;

        for (int i = 0; i < a->array.count; i++) {
            if (result->array.count >= result->array.cap) {
                result->array.cap *= 2;
                result->array.items = xrealloc(result->array.items, sizeof(json_value *) * result->array.cap);
            }
            result->array.items[result->array.count++] = deep_copy(a->array.items[i]);
        }

        for (int i = 0; i < b->array.count; i++) {
            if (!array_contains(result, b->array.items[i])) {
                if (result->array.count >= result->array.cap) {
                    result->array.cap *= 2;
                    result->array.items = xrealloc(result->array.items, sizeof(json_value *) * result->array.cap);
                }
                result->array.items[result->array.count++] = deep_copy(b->array.items[i]);
            }
        }
        return result;
    }

    return deep_copy(b);
}

static void print_string_escaped(const char *s, FILE *f) {
    fputc('"', f);
    for (const char *p = s; *p; p++) {
        unsigned char c = (unsigned char)*p;
        if (c == '"') fputs("\\\"", f);
        else if (c == '\\') fputs("\\\\", f);
        else if (c == '\b') fputs("\\b", f);
        else if (c == '\f') fputs("\\f", f);
        else if (c == '\n') fputs("\\n", f);
        else if (c == '\r') fputs("\\r", f);
        else if (c == '\t') fputs("\\t", f);
        else if (c < 0x20) fprintf(f, "\\u%04x", c);
        else fputc(c, f);
    }
    fputc('"', f);
}

static void print_number(double d, FILE *f) {
    if (isnan(d) || isinf(d)) {
        fputs("null", f);
        return;
    }
    if (d == floor(d) && fabs(d) < 1e15) {
        fprintf(f, "%lld", (long long)d);
    } else {
        char buf[64];
        snprintf(buf, sizeof(buf), "%.15g", d);
        if (strchr(buf, '.') && !strchr(buf, 'e') && !strchr(buf, 'E')) {
            char *end = buf + strlen(buf) - 1;
            while (*end == '0' && end > buf && *(end - 1) != '.') end--;
            if (*end == '.' && end[1] == '\0') end--;
            *end = '\0';
        }
        fputs(buf, f);
    }
}

static void print_value(const json_value *v, int indent, FILE *f) {
    int i;
    switch (v->type) {
        case JSON_NULL:
            fputs("null", f);
            break;
        case JSON_BOOL:
            fputs(v->bool_val ? "true" : "false", f);
            break;
        case JSON_NUMBER:
            print_number(v->number_val, f);
            break;
        case JSON_STRING:
            print_string_escaped(v->string_val, f);
            break;
        case JSON_ARRAY:
            if (v->array.count == 0) {
                fputs("[]", f);
                return;
            }
            fputs("[\n", f);
            for (i = 0; i < v->array.count; i++) {
                for (int j = 0; j < (indent + 1) * 2; j++) fputc(' ', f);
                print_value(v->array.items[i], indent + 1, f);
                if (i < v->array.count - 1) fputc(',', f);
                fputc('\n', f);
            }
            for (int j = 0; j < indent * 2; j++) fputc(' ', f);
            fputc(']', f);
            break;
        case JSON_OBJECT:
            if (v->object.count == 0) {
                fputs("{}", f);
                return;
            }
            int *order = xmalloc(sizeof(int) * v->object.count);
            for (i = 0; i < v->object.count; i++) order[i] = i;
            for (i = 1; i < v->object.count; i++) {
                int key = order[i];
                int j = i - 1;
                while (j >= 0 && strcmp(v->object.keys[order[j]], v->object.keys[key]) > 0) {
                    order[j + 1] = order[j];
                    j--;
                }
                order[j + 1] = key;
            }
            fputs("{\n", f);
            for (i = 0; i < v->object.count; i++) {
                int idx = order[i];
                for (int j = 0; j < (indent + 1) * 2; j++) fputc(' ', f);
                print_string_escaped(v->object.keys[idx], f);
                fputs(": ", f);
                print_value(v->object.values[idx], indent + 1, f);
                if (i < v->object.count - 1) fputc(',', f);
                fputc('\n', f);
            }
            for (int j = 0; j < indent * 2; j++) fputc(' ', f);
            fputc('}', f);
            free(order);
            break;
    }
}

static char *read_file(const char *path, int *out_len) {
    FILE *f = fopen(path, "rb");
    if (!f) {
        fprintf(stderr, "Cannot open %s\n", path);
        exit(1);
    }
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *buf = xmalloc((size_t)sz + 1);
    size_t rd = fread(buf, 1, (size_t)sz, f);
    buf[rd] = '\0';
    fclose(f);
    *out_len = (int)rd;
    return buf;
}

int main(void) {
    const char *path_a = "<tmp>";
    const char *path_b = "<tmp>";

    int len_a, len_b;
    char *buf_a = read_file(path_a, &len_a);
    char *buf_b = read_file(path_b, &len_b);

    parser pa, pb;
    parser_init(&pa, buf_a, len_a);
    parser_init(&pb, buf_b, len_b);

    json_value *va = parse_value(&pa);
    json_value *vb = parse_value(&pb);

    json_value *merged = merge_values(va, vb);

    print_value(merged, 0, stdout);
    fputc('\n', stdout);

    json_free(va);
    json_free(vb);
    json_free(merged);
    free(buf_a);
    free(buf_b);
    return 0;
}
