    private static String fetchJson(String urlStr) {
        try {
            URL url = new URL(urlStr);
            HttpURLConnection conn = (HttpURLConnection) url.openConnection();
            conn.setRequestMethod("GET");
            conn.setConnectTimeout(5000);
            conn.setReadTimeout(5000);
            conn.setRequestProperty("Accept", "application/json");
            conn.setRequestProperty("Accept-Encoding", "identity");

            int code = conn.getResponseCode();
            InputStream is = (code >= 200 && code < 300) ? conn.getInputStream() : conn.getErrorStream();
            if (is == null) {
                return "";
            }

            ByteArrayOutputStream baos = new ByteArrayOutputStream();
            byte[] buf = new byte[4096];
            int n;
            while ((n = is.read(buf)) != -1) {
                baos.write(buf, 0, n);
            }
            is.close();

            String result = new String(baos.toByteArray(), StandardCharsets.UTF_8);
            if (!result.isEmpty() && result.charAt(0) == '\uFEFF') {
                result = result.substring(1);
            }
            return result;
        } catch (IOException e) {
            return "";
        }
    }

    private static List<Product> parseProducts(String json) {
        List<Product> products = new ArrayList<Product>();
        if (json == null || json.trim().isEmpty()) {
            return products;
        }

        try {
            Object parsed = new JsonParser(json).parse();
            if (!(parsed instanceof List)) {
                return products;
            }

            List<?> list = (List<?>) parsed;
            for (int i = 0; i < list.size(); i++) {
                Object item = list.get(i);
                if (!(item instanceof Map)) {
                    continue;
                }

                Map<?, ?> map = (Map<?, ?>) item;
                Object nameObj = map.get("name");
                Object priceObj = map.get("price");

                if (nameObj == null || priceObj == null) {
                    continue;
                }

                String name = nameObj.toString();
                double price;
                if (priceObj instanceof Number) {
                    price = ((Number) priceObj).doubleValue();
                } else {
                    price = Double.parseDouble(priceObj.toString());
                }

                products.add(new Product(name, price));
            }
        } catch (RuntimeException e) {
            return new ArrayList<Product>();
        }

        return products;
    }

    private static class JsonParser {
        private final String s;
        private int i;

        JsonParser(String s) {
            this.s = s;
        }

        Object parse() {
            skipWhitespace();
            if (i >= s.length()) {
                return null;
            }

            char c = s.charAt(i);
            if (c == '[') {
                return parseArray();
            }
            if (c == '{') {
                return parseObject();
            }
            if (c == '"') {
                return parseString();
            }
            if (c == 't') {
                expect("true");
                return Boolean.TRUE;
            }
            if (c == 'f') {
                expect("false");
                return Boolean.FALSE;
            }
            if (c == 'n') {
                expect("null");
                return null;
            }
            return parseNumber();
        }

        private List<Object> parseArray() {
            expect("[");
            List<Object> list = new ArrayList<Object>();

            skipWhitespace();
            if (i >= s.length()) {
                throw new RuntimeException("Unterminated JSON array");
            }
            if (s.charAt(i) == ']') {
                i++;
                return list;
            }

            while (true) {
                skipWhitespace();
                list.add(parse());

                skipWhitespace();
                if (i >= s.length()) {
                    throw new RuntimeException("Unterminated JSON array");
                }

                char c = s.charAt(i);
                if (c == ',') {
                    i++;
                    continue;
                }
                if (c == ']') {
                    i++;
                    break;
                }

                throw new RuntimeException("Expected ',' or ']' in JSON array");
            }

            return list;
        }

        private Map<String, Object> parseObject() {
            expect("{");
            Map<String, Object> map = new LinkedHashMap<String, Object>();

            skipWhitespace();
            if (i >= s.length()) {
                throw new RuntimeException("Unterminated JSON object");
            }
            if (s.charAt(i) == '}') {
                i++;
                return map;
            }

            while (true) {
                skipWhitespace();
                if (i >= s.length()) {
                    throw new RuntimeException("Unterminated JSON object");
                }

                String key = parseString();
                skipWhitespace();
                expect(":");
                Object value = parse();
                map.put(key, value);

                skipWhitespace();
                if (i >= s.length()) {
                    throw new RuntimeException("Unterminated JSON object");
                }

                char c = s.charAt(i);
                if (c == ',') {
                    i++;
                    continue;
                }
                if (c == '}') {
                    i++;
                    break;
                }

                throw new RuntimeException("Expected ',' or '}' in JSON object");
            }

            return map;
        }

        private String parseString() {
            expect("\"");
            StringBuilder sb = new StringBuilder();

            while (true) {
                if (i >= s.length()) {
                    throw new RuntimeException("Unterminated JSON string");
                }

                char c = s.charAt(i++);
                if (c == '"') {
                    break;
                }

                if (c == '\\') {
                    if (i >= s.length()) {
                        throw new RuntimeException("Unterminated JSON string escape");
                    }

                    char e = s.charAt(i++);
                    switch (e) {
                        case '"':
                            sb.append('"');
                            break;
                        case '\\':
                            sb.append('\\');
                            break;
                        case '/':
                            sb.append('/');
                            break;
                        case 'b':
                            sb.append('\b');
                            break;
                        case 'f':
                            sb.append('\f');
                            break;
                        case 'n':
                            sb.append('\n');
                            break;
                        case 'r':
                            sb.append('\r');
                            break;
                        case 't':
                            sb.append('\t');
                            break;
                        case 'u':
                            if (i + 4 > s.length()) {
                                throw new RuntimeException("Invalid Unicode escape");
                            }
                            String hex = s.substring(i, i + 4);
                            i += 4;
                            sb.append((char) Integer.parseInt(hex, 16));
                            break;
                        default:
                            throw new RuntimeException("Invalid JSON escape");
                    }
                } else {
                    sb.append(c);
                }
            }

            return sb.toString();
        }

        private Object parseNumber() {
            int start = i;

            if (i < s.length() && s.charAt(i) == '-') {
                i++;
            }

            while (i < s.length() && Character.isDigit(s.charAt(i))) {
                i++;
            }

            if (i < s.length() && s.charAt(i) == '.') {
                i++;
                while (i < s.length() && Character.isDigit(s.charAt(i))) {
                    i++;
                }
            }

            if (i < s.length() && (s.charAt(i) == 'e' || s.charAt(i) == 'E')) {
                i++;
                if (i < s.length() && (s.charAt(i) == '+' || s.charAt(i) == '-')) {
                    i++;
                }
                while (i < s.length() && Character.isDigit(s.charAt(i))) {
                    i++;
                }
            }

            String num = s.substring(start, i);
            return Double.parseDouble(num);
        }

        private void expect(String str) {
            for (int k = 0; k < str.length(); k++) {
                if (i + k >= s.length() || s.charAt(i + k) != str.charAt(k)) {
                    throw new RuntimeException("Expected '" + str + "' at position " + i);
                }
            }
            i += str.length();
        }

        private void skipWhitespace() {
            while (i < s.length() && Character.isWhitespace(s.charAt(i))) {
                i++;
            }
        }
    }
